INSERT [dbo].[ContactUs] ([Id], [Name], [Email], [Subject], [ContactDate]) VALUES (8186, N'Stephen Gates', N'stephen@erceasy.com', N'Hello, it''s Stephen from ERC Concepts in Miami. 

