CREATE PROCEDURE [ahmedshair].[DeleteQuestionById]  
@QuestionID int  
AS  
BEGIN  
 Delete  from Questions  
 where QuestionID= @QuestionID 
 IF @@ROWCOUNT = 0
 BEGIN
	DELETE FROM PPSCQUESTIONS WHERE QUESTIONID = @QuestionID
 END
END  
