CREATE PROCEDURE [ahmedshair].[GetAllFPSCQuestionsByPaperID]
@PaperID INT
AS
BEGIN
SELECT QuestionID,q.PaperID,s.PaperName,QuestionStatement,Choices,CorrectAnswer 
FROM FPSCQuestions q
inner join FPSCPaper s on s.PaperID= q.PaperID
where q.PaperID= @PaperID
END

