SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [ahmedshair].[GetAllPaper]
AS
BEGIN
	Select Y.YearValue,J.PostName,	P.* from PPSCPaper P
	LEFT JOIN PaperYear Y ON Y.YearID = P.YearID
	LEFT JOIN JobPost J ON J.PostID = P.PostID
END

GO
