SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [ahmedshair].[GetAllQuestionsByPaperID]
@PaperID INT
AS
BEGIN
SELECT QuestionID,q.PaperID,s.PaperName,QuestionStatement,NumberOfChoices,Choices,CorrectAnswer,Sub.SubjectName
FROM PPSCQuestions q
inner join PPSCPaper s on s.PaperID= q.PaperID
LEFT JOIN [Subject] Sub on Sub.SubjectID = Q.SubjectID
where q.PaperID= @PaperID
END

GO
/****** Object:  StoredProcedure [ahmedshair].[GetAllQuestionsBySubjectID]    Script Date: 11/6/2023 10:15:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [ahmedshair].[GetAllQuestionsBySubjectID]
@SubjectID INT
AS
BEGIN

	CREATE TABLE #SubjectQUESTIONS (
	QuestionID INT,
	SubjectID INT,
	SubjectName NVARCHAR(MAX),
	QuestionStatement NVARCHAR(MAX),
	NumberOfChoices INT,
	Choices NVARCHAR(MAX),
	CorrectAnswer NVARCHAR(MAX),
	PaperID INT)

INSERT INTO #SubjectQUESTIONS (QuestionID,SubjectID,SubjectName,QuestionStatement,NumberOfChoices,Choices,CorrectAnswer,PaperID)
SELECT QuestionID,q.SubjectID,s.SubjectName,QuestionStatement,NumberOfChoices,Choices,CorrectAnswer,0
FROM Questions q
INNER JOIN SUBJECT S ON s.SubjectID= q.SubjectID
WHERE q.SubjectID= @SubjectID

INSERT INTO #SubjectQUESTIONS (QuestionID,SubjectID,SubjectName,QuestionStatement,NumberOfChoices,Choices,CorrectAnswer,PaperID) 
SELECT QuestionID,q.SubjectID,s.SubjectName,QuestionStatement,NumberOfChoices,Choices,CorrectAnswer,paperid
FROM ppscQuestions q
INNER JOIN SUBJECT S ON s.SubjectID= q.SubjectID
WHERE q.SubjectID=@SubjectID

SELECT * FROM #SubjectQUESTIONS ORDER BY PaperID ASC
DROP TABLE #SubjectQUESTIONS

END


