/****** Object:  StoredProcedure [ahmedshair].[SearchPPSCPaperYearwise]    Script Date: 11/6/2023 10:15:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [ahmedshair].[SearchPPSCPaperYearwise]
@YearID int 
AS  
BEGIN  
 Select Y.YearValue,J.PostName, P.* from PPSCPaper P  
 LEFT JOIN [ahmedshair].PaperYear Y ON Y.YearID = P.YearID  
 LEFT JOIN [ahmedshair].JobPost J ON J.PostID = P.PostID
 WHERE Y.YearID = @YearID
END  
  
GO
