/****** Object:  StoredProcedure [ph16200308291].[GETQuizByID]    Script Date: 11/6/2023 10:15:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [ph16200308291].[GETQuizByID] --114
@QUIZID INT
AS
BEGIN
SELECT * FROM QUIZ U
JOIN QUIZQUESTIONS Z ON Z.QUIZID = U.QUIZID
JOIN QUESTIONS Q ON Q.QUESTIONID = Z.QUESTIONID
JOIN SUBJECT S ON S.SUBJECTID = U.SUBJECTID
WHERE Z.QUIZID = @QUIZID
END
GO
/****** Object:  StoredProcedure [ph16200308291].[GETUSERQUIZ]    Script Date: 11/6/2023 10:15:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [ph16200308291].[GETUSERQUIZ]
@USERID INT
AS
BEGIN
SELECT QUIZID, TITLE, SCORE,TOTALQUESTIONS,TIMELIMIT,INSERTDATE,UPDATEDATE,TOTALATTEMPT,ALLOWEDATTEMPT, S.SubjectName
FROM QUIZ Q
JOIN Subject S ON S.SUBJECTID = Q.SUBJECTID
WHERE Q.USERID = @USERID
ORDER BY QUIZID DESC
END
GO
/****** Object:  StoredProcedure [ph16200308291].[INSERTQUIZ]    Script Date: 11/6/2023 10:15:45 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [ph16200308291].[INSERTQUIZ]  
    @TITLE NVARCHAR(500),  
    @USERID INT,  
 @SUBJECTID INT,  
    @SCORE NVARCHAR(15),  
 @TOTALQUESTIONS INT,  
 @TIMELIMIT INT,  
 @TOTALATTEMPT INT,  
 @ALLOWEDATTEMPT INT  
AS    
BEGIN    
INSERT INTO QUIZ(  
    TITLE ,  
    USERID ,  
 SUBJECTID,  
    SCORE ,  
 TOTALQUESTIONS,  
 TIMELIMIT ,  
 TOTALATTEMPT,  
 ALLOWEDATTEMPT) VALUES (@TITLE ,  
    @USERID ,  
 @SUBJECTID,  
    @SCORE ,  
 @TOTALQUESTIONS,  
 @TIMELIMIT ,  
 @TOTALATTEMPT,  
 @ALLOWEDATTEMPT)
 
 SELECT SCOPE_IDENTITY() AS QuizID

 SELECT TOP (@TOTALQUESTIONS) Q.QUESTIONID,Q.QuestionID,Q.QuestionStatement,Q.NumberOfChoices,Q.Choices,Q.CorrectAnswer,Q.SubjectID, S.SUBJECTName FROM QUESTIONS Q
 JOIN SUBJECT S ON S.SUBJECTID=Q.SUBJECTID
    WHERE Q.SubjectID =@SUBJECTID
    ORDER BY NEWID()
END
GO
