SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [ph16200308291].[UPDATEQUIZ]
@QUIZID INT,
@SCORE INT
AS
BEGIN
UPDATE QUIZ
SET SCORE = @SCORE, TOTALATTEMPT = TOTALATTEMPT + 1
WHERE QUIZID = @QUIZID
END
